    # hardsigmoid: y = clamp(x/6 + 0.5, 0, 1)
    # grad: 1/6 when -3 < x < 3 (strict), else 0.
    # The range test is evaluated on the raw input dtype: the comparison is
    # exact because +-3 are representable in fp16/bf16, and |s| < 3 is
    # equivalent to (-3 < s) & (s < 3) including for NaN (false -> 0).
    inr = tl.abs(s) < 3.0
    return tl.where(inr, g * 0.16666666666666666, 0.0)


